import {dailyRate,priceFor} from './pricing-core.mjs';
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('ru-RU').format(n),config=window.RENTAL_CONFIG||{},esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog,filter='all',usage='all',copyText='',generation=0;
const now=Date.now(),local=d=>new Date(d+10800000).toISOString().slice(0,16);$('#start').min=local(now);$('#start').value=local(Math.ceil((now+86400000)/3600000)*3600000);$('#end').value=local(Math.ceil((now+4*86400000)/3600000)*3600000);
function period(){const a=Date.parse($('#start').value+'+03:00'),b=Date.parse($('#end').value+'+03:00');if(!Number.isFinite(a)||!Number.isFinite(b)||a<=Date.now())throw Error('Выберите дату и время получения в будущем.');if(b<=a)throw Error('Возврат должен быть позже получения.');if(b-a>90*86400000)throw Error('Для срока более 90 суток обратитесь к менеджеру.');return{start:new Date(a).toISOString(),end:new Date(b).toISOString(),days:Math.ceil((b-a)/86400000),route:$('#route').value,equipment:$('#equipment').value,pickup:$('#pickup').value};}
function validate(){try{const p=period();$('#date-error').textContent='';return p;}catch(e){$('#date-error').textContent=e.message;return null;}}
function render(){if(!catalog)return;let days=3;try{days=period().days;}catch{}$('#period-hint').textContent=days>=25?'От 25 суток — договорная цена':`Тариф для ${days} сут. аренды`;
$('#cars').innerHTML=catalog.cars.filter(c=>(filter==='all'||c.category===filter)&&(usage==='all'||c.uses?.includes(usage))).map(c=>{const rate=dailyRate(c,days);return `<article class="car"><div class="car-image"><img src="${esc(c.image)}" alt="${esc(c.name)} — ${c.imageKind==='generated'?'сгенерированная иллюстрация модели':'фотография из автопарка'}" loading="lazy"></div><div class="car-body"><div class="car-badges"><span class="class-tag">${esc(c.label)}</span>${c.imageKind==='generated'?'<span class="ai-photo-label">ИИ-иллюстрация модели</span>':''}</div><h3>${esc(c.name)}</h3><div class="specs"><span>${c.year} г.</span><span>${c.gear}</span><span>${c.seats} мест</span><span>Кондиционер</span></div><button class="gallery-button" data-gallery="${c.id}">Фото и все тарифы ↗</button><div class="car-bottom"><div class="price">${rate===null?'Договорная':money(rate)+' ₽'} ${rate===null?'':'<small>/ сутки</small>'}</div><button data-car="${c.id}">Выбрать <span class="cta-arrow">↗</span></button></div><p class="deposit-note">Залог: ${money(c.deposit)} ₽ · отдельно от аренды</p></div></article>`;}).join('');if(!$('#cars').children.length)$('#cars').innerHTML='<p class="empty-filter">Такого сочетания пока нет. Выберите другой класс или назначение.</p>';document.querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>choose(b.dataset.car));document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>gallery(b.dataset.gallery));}
function gallery(id){const c=catalog.cars.find(x=>x.id===id),dialog=document.createElement('dialog');let frame=0;dialog.innerHTML=`<button class="close" aria-label="Закрыть фотографии">×</button><span class="kicker">РЕАЛЬНЫЙ АВТОПАРК</span><h2>${esc(c.name)}</h2><img class="gallery-photo" alt="${esc(c.name)}" src="${esc(c.gallery[0])}"><div class="gallery-controls"><button data-prev aria-label="Предыдущее фото">←</button><span data-counter>1 / ${c.gallery.length}</span><button data-next aria-label="Следующее фото">→</button></div><table class="tariff-table"><thead><tr><th>Срок</th><th>Цена за сутки</th></tr></thead><tbody>${['1 сутки','2 суток','3–6 суток','7–14 суток','15–24 суток'].map((l,i)=>`<tr><td>${l}</td><td>${money(c.rates[i])} ₽</td></tr>`).join('')}<tr><td>От 25 суток</td><td>Договорная</td></tr></tbody></table><p>Залог: ${money(c.deposit)} ₽. Подача, возврат и особые маршруты — отдельно.</p><a class="source-link" href="${esc(c.source)}" target="_blank" rel="noopener">Карточка на исходном сайте ↗</a>`;document.body.append(dialog);dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());function change(n){frame=(frame+n+c.gallery.length)%c.gallery.length;dialog.querySelector('img').src=c.gallery[frame];dialog.querySelector('[data-counter]').textContent=`${frame+1} / ${c.gallery.length}`;}dialog.querySelector('[data-prev]').onclick=()=>change(-1);dialog.querySelector('[data-next]').onclick=()=>change(1);dialog.showModal();}
function choose(id){const p=validate();if(!p){travelTo($('#booking'));return;}const c=catalog.cars.find(x=>x.id===id),q=priceFor(catalog,c,p.days,p.route,p.equipment),fmt=s=>new Date(s).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',dateStyle:'short',timeStyle:'short'});const current=++generation;$('#selected-name').textContent=c.name;copyText=`${c.name}\nПолучение: ${fmt(p.start)}\nВозврат: ${fmt(p.end)}\nМесто: ${p.pickup}\nПериод: ${p.days} сут.\n${q.negotiated?'Цена аренды: договорная':`Аренда: ${p.days} × ${money(q.rate)} = ${money(q.rent)} ₽`}\nМаршрут: ${catalog.routes[p.route].name} · ${money(q.routeFee)} ₽\nОборудование: ${catalog.equipment[p.equipment].name} · ${money(q.equipmentFee)} ₽\n${q.negotiated?'Итог согласует менеджер':`Предварительно: ${money(q.total)} ₽`}\nЗалог: ${money(q.deposit)} ₽ отдельно\nПодача и возврат: согласуются отдельно.`;$('#summary').textContent=copyText;$('#copy-status').textContent='';$('#bot-link').hidden=true;$('#bot-status').textContent=config.apiBase?'Передаём автомобиль и даты Михаилу…':'Михаил поможет выбрать машину и даты прямо в Telegram. Расчёт с этой страницы можно скопировать.';if(config.botUsername){$('#bot-link').href='https://t.me/'+config.botUsername;$('#bot-link').textContent='Открыть бота Михаила ↗';$('#bot-link').hidden=false;}$('#booking-dialog').showModal();if(config.apiBase&&config.botUsername)handoff(c,p,current);}
async function handoff(c,p,current){try{const r=await fetch(config.apiBase.replace(/\/$/,'')+'/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...p,car_id:c.id}),signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();const j=await r.json();if(current!==generation||!$('#booking-dialog').open)return;if(!/^[a-zA-Z0-9_-]{10,64}$/.test(j.token))throw Error();$('#bot-link').href=`https://t.me/${config.botUsername}?start=${j.token}`;$('#bot-status').textContent='Автомобиль, даты и расчет передадутся Михаилу по номеру заявки. Наличие и условия подтверждает менеджер.';}catch{if(current===generation)$('#bot-status').textContent='Не удалось передать заявку серверу. Скопируйте расчет и попробуйте позже. Бронь не подтверждена.';}}
$('.close').onclick=()=>$('#booking-dialog').close();$('#booking-dialog').addEventListener('close',()=>generation++);$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(copyText);$('#copy-status').textContent='Расчет скопирован.';}catch{$('#copy-status').textContent='Выделите и скопируйте расчет вручную.';}};$('#find').onclick=()=>{if(validate()){travelTo($('#fleet'));render();}};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;if(usage!=='all'&&!catalog.cars.some(c=>(filter==='all'||c.category===filter)&&c.uses?.includes(usage))){usage='all';document.querySelectorAll('[data-use]').forEach(x=>{x.classList.toggle('active',x.dataset.use==='all');x.setAttribute('aria-pressed',String(x.dataset.use==='all'));});}document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();});document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{usage=b.dataset.use;document.querySelectorAll('[data-use]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();});['#start','#end','#route','#equipment'].forEach(s=>$(s).addEventListener('change',render));
const buddy=$('#road-buddy'),toggle=$('#effects-toggle'),motionQuery=matchMedia('(prefers-reduced-motion: reduce)');let effects=!motionQuery.matches,hovered=false,elapsed=0,previousTime=0,jokeIndex=0,turnIndex=-1,lastAuto=0,spokenUntil=performance.now()+4500;
const jokes=['Не гоню. Красиво еду!','Навигатор сказал: пора в отпуск.','Я заправился впечатлениями!','В багажнике место для приключений.','Поворот не туда? Значит, экскурсия!'];
buddy.onclick=()=>{buddy.querySelector('.buddy-speech').textContent=jokes[++jokeIndex%jokes.length];spokenUntil=performance.now()+5000;};
buddy.addEventListener('pointerenter',()=>hovered=true);buddy.addEventListener('pointerleave',()=>hovered=false);buddy.addEventListener('focus',()=>hovered=true);buddy.addEventListener('blur',()=>hovered=false);
function patrol(time){const dt=previousTime?Math.min(64,time-previousTime):0;previousTime=time;if(effects&&!hovered&&!document.hidden)elapsed+=dt;const width=buddy.getBoundingClientRect().width,max=Math.max(0,innerWidth-width-30),duration=Math.max(45000,max/12*1000),phase=(elapsed/duration)%2,forward=phase<1,x=15+(forward?phase:2-phase)*max;buddy.style.left=(effects?x:Math.max(15,innerWidth-width-20))+'px';buddy.style.setProperty('--buddy-facing',forward?'-1':'1');const speech=buddy.querySelector('.buddy-speech');const bubbleWidth=Math.min(175,document.documentElement.clientWidth-24);speech.style.width=bubbleWidth+'px';speech.style.left=(Math.max(12,Math.min(x,document.documentElement.clientWidth-bubbleWidth-12))-x)+'px';speech.style.right='auto';const turn=Math.floor(elapsed/duration);if(effects&&(turn!==turnIndex||elapsed-lastAuto>14000)){turnIndex=turn;lastAuto=elapsed;buddy.querySelector('.buddy-speech').textContent=jokes[++jokeIndex%jokes.length];spokenUntil=time+7000;}buddy.classList.toggle('is-speaking',time<spokenUntil||hovered);requestAnimationFrame(patrol);}requestAnimationFrame(patrol);
function motion(){document.body.classList.toggle('effects-off',!effects);toggle.setAttribute('aria-pressed',String(!effects));toggle.textContent=effects?'Ⅱ Эффекты':'▶ Эффекты';}toggle.onclick=()=>{effects=!effects;motion();};motionQuery.addEventListener('change',e=>{effects=!e.matches;motion();});motion();
let scrolling=0,scrollToken=0;function stopScrolling(){cancelAnimationFrame(scrolling);scrollToken++;document.documentElement.style.scrollBehavior='';}addEventListener('wheel',stopScrolling,{passive:true});addEventListener('touchstart',stopScrolling,{passive:true});
function travelTo(target){stopScrolling();const token=scrollToken,start=scrollY,header=document.querySelector('.header').getBoundingClientRect().height,end=Math.max(0,target.getBoundingClientRect().top+start-header-22),distance=end-start;if(motionQuery.matches){window.scrollTo({top:end,behavior:'instant'});return;}document.documentElement.style.scrollBehavior='auto';const began=performance.now(),duration=Math.min(950,Math.max(500,Math.abs(distance)*.35));function step(now){if(token!==scrollToken)return;const t=Math.min(1,(now-began)/duration),ease=t*t*(3-2*t);window.scrollTo({top:start+distance*ease,behavior:'instant'});if(t<1)scrolling=requestAnimationFrame(step);else document.documentElement.style.scrollBehavior='';}scrolling=requestAnimationFrame(step);}
document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const id=a.getAttribute('href'),target=document.querySelector(id==='#'?'#top':id);if(!target)return;e.preventDefault();travelTo(target);if(location.hash!==id)history.pushState(null,'',id);}));
document.querySelectorAll('.button,.text-link,.header-button').forEach(a=>a.classList.add('arrow-link'));const partner=document.querySelector('.partner-pending');if(partner){const a=document.createElement('a');a.href='https://stomkmv.ru/';a.target='_blank';a.rel='noopener';a.className='partner-visit';a.textContent='Перейти на сайт ↗';partner.replaceWith(a);document.querySelector('.partner-card p').textContent='Семейная стоматология в Минеральных Водах.';}
try{const response=await fetch('catalog.json', {cache:'no-store'});if(!response.ok)throw Error();catalog=await response.json();render();}catch{$('#cars').textContent='Не удалось загрузить каталог. Обновите страницу или позвоните +7 (988) 108-74-78.';}


const sectionHints={welcome:'Горы ждут! Выберем машину под вашу поездку?',booking:'Укажите даты и время — посчитаем аренду.',fleet:'Сравните классы и нажмите «Выбрать» у понравившейся машины.',routes:'Нажмите на красивое место — откроется карта.',guide:'Сохраните лайфхаки перед поездкой!',conditions:'Проверьте документы, залог и условия заранее.',partners:'Наш партнёр — «Семейная стоматология».'};
let buddySection='',buddyScrollTimer;
function sectionSuggestion(){const target=Object.keys(sectionHints).map(id=>document.getElementById(id)).filter(Boolean).filter(el=>{const r=el.getBoundingClientRect();return r.top<innerHeight*.6&&r.bottom>150;}).at(-1);if(!target||target.id===buddySection)return;buddySection=target.id;buddy.querySelector('.buddy-speech').textContent=sectionHints[target.id];spokenUntil=performance.now()+8000;lastAuto=elapsed;hovered=buddy.matches(':hover');}
addEventListener('scroll',()=>{clearTimeout(buddyScrollTimer);buddyScrollTimer=setTimeout(sectionSuggestion,150);},{passive:true});

// Catalog rendering and local font loading can move an initially linked section.
let initialNavigationInterrupted=false;
for(const event of ['wheel','touchstart','pointerdown','keydown'])addEventListener(event,()=>{initialNavigationInterrupted=true;},{once:true,passive:true});
if(location.hash){
  const initialHash=location.hash;
  await document.fonts.ready;
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    if(initialNavigationInterrupted||location.hash!==initialHash)return;
    let id;try{id=decodeURIComponent(initialHash.slice(1));}catch{return;}
    const target=document.getElementById(id);if(!target)return;
    stopScrolling();
    const header=document.querySelector('#site-header').getBoundingClientRect().height;
    window.scrollTo({top:Math.max(0,target.getBoundingClientRect().top+scrollY-header-22),behavior:'instant'});
    sectionSuggestion();
  }));
}
